// Holds a flat string blob and its offset table for one language
struct LangStrings {
  const char* data;
  const uint32_t* offsets;
};

// Helper function to get string data for a language
inline LangStrings getLanguageStrings(Language lang) {
  switch (lang) {
    case Language::EN:
      return {i18n_strings::STRINGS_EN_DATA, i18n_strings::OFFSETS_EN};
    case Language::ZH_CN:
      return {i18n_strings::STRINGS_ZH_CN_DATA, i18n_strings::OFFSETS_ZH_CN};
    case Language::ZH_TW:
      return {i18n_strings::STRINGS_ZH_TW_DATA, i18n_strings::OFFSETS_ZH_TW};
    default:
      return {i18n_strings::STRINGS_EN_DATA, i18n_strings::OFFSETS_EN};
  }
}

// Helper function to get language count
constexpr uint8_t getLanguageCount() { return static_cast<uint8_t>(Language::_COUNT); }

// Sorted language indices by _bcp47 (auto-generated by gen_i18n.py)
//    0: EN   en       English
//    1: ZH_CN zh-CN    简体中文
//    2: ZH_TW zh-TW    繁體中文
constexpr uint8_t SORTED_LANGUAGE_INDICES[] = {0, 1, 2};

static_assert(sizeof(SORTED_LANGUAGE_INDICES) / sizeof(SORTED_LANGUAGE_INDICES[0]) == getLanguageCount(),
              "SORTED_LANGUAGE_INDICES size mismatch");

